import java.util.Scanner;

public class Main {
    static long n, m;
    static long[] visitedArray = new long[1000006];
    static long countCycles;

    static long fastPower(long base, long exp) {
        long result = 1;
        for (int i = 30; i >= 0; i--) {
            result = (result * result) % 1000000007;
            if (((long)1 << i & exp) != 0) {
                result = (result * base) % 1000000007;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        countCycles = 0;
        n = sc.nextLong();
        m = sc.nextLong();

        if (m == 1) {
            System.out.println(fastPower(n, n));
            return;
        }

        for (long i = 1; i < n; i++) {
            if (visitedArray[(int)i] == 0) {
                visitedArray[(int)i] = 1;
                countCycles++;
                long currentValue = (i * m) % n;
                while (visitedArray[(int)currentValue] == 0) {
                    visitedArray[(int)currentValue] = 1;
                    currentValue = (currentValue * m) % n;
                }
            }
        }
        System.out.println(fastPower(n, countCycles));
        sc.close();
    }
}
